function rh24_label_schema_health(PDO $db): array {
    $missing=[];foreach(rh24_label_required_tables() as $t){try{$q=$db->prepare('SHOW TABLES LIKE ?');$q->execute([$t]);if(!$q->fetchColumn())$missing[]=$t;}catch(Throwable){$missing[]=$t;}}
