function rh24_seed_v965_media(PDO $db): void {
    $st=$db->prepare("INSERT INTO label_media(id,name,manufacturer,media_code,media_kind,width_mm,height_mm,paper_size,`cols`,`rows`,technology,unit_name,stock_units,min_stock_units,settings_json,is_system,status,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,1,'active',NOW(),NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name),manufacturer=VALUES(manufacturer),media_code=VALUES(media_code),media_kind=VALUES(media_kind),width_mm=VALUES(width_mm),height_mm=VALUES(height_mm),paper_size=VALUES(paper_size),`cols`=VALUES(`cols`),`rows`=VALUES(`rows`),technology=VALUES(technology),unit_name=VALUES(unit_name),settings_json=VALUES(settings_json),is_system=1,status='active',updated_at=NOW()");
    foreach(rh24_label_media_seed() as $m){try{$st->execute([$m[0],$m[1],$m[2],$m[3],$m[4],$m[5],$m[6],$m[7],$m[8],$m[9],$m[10],$m[11],$m[12],$m[13],rh24_json_encode($m[14])]);}catch(Throwable){}}
}
function rh24_label_media_compatible(array $media,array $printer): bool {
    if(($media['status']??'')!=='active'||($printer['status']??'')!=='active')return false;
    $ms=is_array($media['settings']??null)?$media['settings']:rh24_json_decode((string)($media['settings_json']??''),[]);
    $ps=is_array($printer['settings']??null)?$printer['settings']:rh24_json_decode((string)($printer['settings_json']??''),[]);
    $pc=strtolower((string)($ps['printer_class']??''));$pt=strtolower((string)($ps['technology']??'universal'));$pm=strtolower((string)($printer['manufacturer']??''));$mm=strtolower((string)($media['manufacturer']??''));$model=strtolower((string)($printer['model']??''));
    if($mm==='brother'&&str_starts_with((string)($media['media_code']??''),'DK-')&&!str_contains($pc,'label'))return false;
    $models=array_map(fn($v)=>strtolower((string)$v),is_array($ms['compatible_models']??null)?$ms['compatible_models']:[]);if($models)return in_array($model,$models,true);
    $makers=array_map(fn($v)=>strtolower((string)$v),is_array($ms['compatible_manufacturers']??null)?$ms['compatible_manufacturers']:[]);
    $tech=array_map(fn($v)=>strtolower((string)$v),is_array($ms['compatible_technologies']??null)?$ms['compatible_technologies']:[]);
    $kind=(string)($media['media_kind']??'');
    if(in_array($kind,['diecut_sheet','plain_sheet'],true)){
        $office=str_starts_with($pc,'office')||$pc==='office'||$pc===''||in_array($pt,['universal','inkjet','laser'],true);if(!$office)return false;
        if($tech&&!in_array('universal',$tech,true)){ $ok=false;foreach($tech as $t){if(str_contains($pt,$t)||str_contains($t,$pt)||$pt==='universal'){$ok=true;break;}}if(!$ok)return false; }
        if($makers&&!in_array($pm,$makers,true))return false;return true;
    }
    if(str_starts_with($pc,'office'))return false;if($makers)return in_array($pm,$makers,true);
    if($tech){foreach($tech as $t)if(str_contains($pt,$t)||str_contains($t,$pt))return true;return false;}
    return $mm==='generic'||$mm===$pm;
}

function rh24_label_media(): array {
    $rows=rh24_db()->query("SELECT * FROM label_media WHERE status<>'deleted' ORDER BY manufacturer,name")->fetchAll();
    foreach($rows as &$r){$r['width_mm']=(float)$r['width_mm'];$r['height_mm']=(float)$r['height_mm'];$r['cols']=(int)$r['cols'];$r['rows']=(int)$r['rows'];$r['stock_units']=(float)$r['stock_units'];$r['min_stock_units']=(float)$r['min_stock_units'];$r['is_system']=(bool)$r['is_system'];$r['settings']=rh24_json_decode((string)($r['settings_json']??''),[]);unset($r['settings_json']);}unset($r);return $rows;
}
function rh24_ensure_v96_label_schema(PDO $db): void {
    $db->exec("CREATE TABLE IF NOT EXISTS label_printers (
      id VARCHAR(60) NOT NULL PRIMARY KEY, name VARCHAR(160) NOT NULL, manufacturer VARCHAR(80) NOT NULL DEFAULT 'Generic', model VARCHAR(160) NOT NULL DEFAULT '', connection_type VARCHAR(30) NOT NULL DEFAULT 'system', output_mode VARCHAR(30) NOT NULL DEFAULT 'system_print', bridge_url VARCHAR(500) NOT NULL DEFAULT '', bridge_token VARCHAR(500) NOT NULL DEFAULT '', dpi SMALLINT UNSIGNED NOT NULL DEFAULT 300, default_width_mm DECIMAL(7,2) NOT NULL DEFAULT 62.00, default_height_mm DECIMAL(7,2) NOT NULL DEFAULT 29.00, media_code VARCHAR(80) NOT NULL DEFAULT '', orientation VARCHAR(20) NOT NULL DEFAULT 'landscape', copies SMALLINT UNSIGNED NOT NULL DEFAULT 1, darkness SMALLINT NOT NULL DEFAULT 0, speed SMALLINT NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'active', is_default TINYINT(1) NOT NULL DEFAULT 0, settings_json LONGTEXT NULL, notes VARCHAR(500) NOT NULL DEFAULT '', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, KEY idx_label_printer_status(status,is_default)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $db->exec("CREATE TABLE IF NOT EXISTS label_media (
      id VARCHAR(60) NOT NULL PRIMARY KEY, name VARCHAR(180) NOT NULL, manufacturer VARCHAR(80) NOT NULL DEFAULT 'Generic', media_code VARCHAR(80) NOT NULL DEFAULT '', media_kind VARCHAR(30) NOT NULL DEFAULT 'diecut_roll', width_mm DECIMAL(7,2) NOT NULL DEFAULT 62.00, height_mm DECIMAL(7,2) NOT NULL DEFAULT 29.00, paper_size VARCHAR(30) NOT NULL DEFAULT '', `cols` SMALLINT UNSIGNED NOT NULL DEFAULT 0, `rows` SMALLINT UNSIGNED NOT NULL DEFAULT 0, technology VARCHAR(40) NOT NULL DEFAULT 'universal', unit_name VARCHAR(30) NOT NULL DEFAULT 'Stück', stock_units DECIMAL(10,2) NOT NULL DEFAULT 0.00, min_stock_units DECIMAL(10,2) NOT NULL DEFAULT 0.00, settings_json LONGTEXT NULL, is_system TINYINT(1) NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, KEY idx_label_media_kind(media_kind,status), KEY idx_label_media_stock(stock_units,min_stock_units)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $db->exec("CREATE TABLE IF NOT EXISTS label_templates (
      id VARCHAR(60) NOT NULL PRIMARY KEY, name VARCHAR(160) NOT NULL, category VARCHAR(50) NOT NULL DEFAULT 'product', width_mm DECIMAL(7,2) NOT NULL DEFAULT 62.00, height_mm DECIMAL(7,2) NOT NULL DEFAULT 29.00, orientation VARCHAR(20) NOT NULL DEFAULT 'landscape', layout_json LONGTEXT NOT NULL, is_system TINYINT(1) NOT NULL DEFAULT 0, is_favorite TINYINT(1) NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL DEFAULT 'active', created_by VARCHAR(60) NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, KEY idx_label_template_cat(category,status)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $db->exec("CREATE TABLE IF NOT EXISTS label_jobs (
      id VARCHAR(60) NOT NULL PRIMARY KEY, job_no VARCHAR(80) NOT NULL, template_id VARCHAR(60) NULL, printer_id VARCHAR(60) NULL, job_type VARCHAR(40) NOT NULL DEFAULT 'single', status VARCHAR(30) NOT NULL DEFAULT 'draft', source_type VARCHAR(40) NOT NULL DEFAULT 'manual', source_ref VARCHAR(100) NOT NULL DEFAULT '', label_count INT UNSIGNED NOT NULL DEFAULT 0, copy_count SMALLINT UNSIGNED NOT NULL DEFAULT 1, payload_json LONGTEXT NULL, error_message VARCHAR(700) NOT NULL DEFAULT '', printed_by VARCHAR(60) NULL, printed_at DATETIME NULL, created_by VARCHAR(60) NULL, created_at DATETIME NOT NULL, updated_at DATETIME NOT NULL, UNIQUE KEY uq_label_job_no(job_no), KEY idx_label_job_status(status,created_at)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $db->exec("CREATE TABLE IF NOT EXISTS label_job_items (
      id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY, job_id VARCHAR(60) NOT NULL, line_no INT UNSIGNED NOT NULL, copies SMALLINT UNSIGNED NOT NULL DEFAULT 1, data_json LONGTEXT NOT NULL, created_at DATETIME NOT NULL, KEY idx_label_job_item(job_id,line_no)
    ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    try{$cnt=(int)$db->query('SELECT COUNT(*) FROM label_printers')->fetchColumn();if($cnt===0){
      $st=$db->prepare("INSERT INTO label_printers(id,name,manufacturer,model,connection_type,output_mode,dpi,default_width_mm,default_height_mm,media_code,orientation,copies,status,is_default,settings_json,notes,created_at,updated_at) VALUES(?,?,?,?,?,?,?,?,?,?,?,1,'active',1,?,?,NOW(),NOW())");
      $st->execute(['LP-QL800','Brother QL-800','Brother','QL-800','usb/system','system_print',300,62,29,'DK-11209 / DK-Rolle','landscape',rh24_json_encode(['supports_red_black'=>true,'recommended_driver'=>'Brother macOS/Windows Treiber','direct_mode_note'=>'Universell über Systemdruck/PDF; optionale lokale Bridge für Direktdruck.']),'V96 Startprofil passend zum vorhandenen Brother QL-800.']);
    }}catch(Throwable){}
    try{rh24_seed_v965_printer_profiles($db);}catch(Throwable){}
    try{rh24_seed_v965_media($db);}catch(Throwable){}
    $templateSetReady=false;
    try{
      $st=$db->prepare("INSERT INTO label_templates(id,name,category,width_mm,height_mm,orientation,layout_json,is_system,is_favorite,status,created_by,created_at,updated_at)
        VALUES(?,?,?,?,?,?,?,1,?,'active',NULL,NOW(),NOW())
        ON DUPLICATE KEY UPDATE name=VALUES(name),category=VALUES(category),width_mm=VALUES(width_mm),height_mm=VALUES(height_mm),orientation=VALUES(orientation),layout_json=VALUES(layout_json),is_system=1,status='active',updated_at=NOW()");
      foreach(rh24_label_system_templates_v964() as $t){
        $st->execute([$t['id'],$t['name'],$t['category'],$t['width_mm'],$t['height_mm'],$t['orientation'],rh24_json_encode($t['layout']),$t['favorite']]);
      }
      $q=$db->query("SELECT COUNT(*) FROM label_templates WHERE is_system=1 AND status='active'");
      $templateSetReady=((int)$q->fetchColumn()>=100);
    }catch(Throwable){}
    $mediaReady=false;try{$mediaReady=((int)$db->query("SELECT COUNT(*) FROM label_media WHERE status='active'")->fetchColumn()>=20);}catch(Throwable){}
    rh24_setting_set('label_schema_version',($templateSetReady&&$mediaReady)?'965':'96');
}
function rh24_label_ensure_ready(): array {$db=rh24_db();$h=rh24_label_schema_health($db);$tplCount=0;$mediaCount=0;try{$tplCount=(int)$db->query("SELECT COUNT(*) FROM label_templates WHERE is_system=1 AND status='active'")->fetchColumn();}catch(Throwable){}try{$mediaCount=(int)$db->query("SELECT COUNT(*) FROM label_media WHERE status='active'")->fetchColumn();}catch(Throwable){}if(!$h['ready']||((int)($h['version']??0)<965)||$tplCount<100||$mediaCount<20){rh24_ensure_v96_label_schema($db);$h=rh24_label_schema_health($db);}return $h;}
function rh24_label_printers(): array {$rows=rh24_db()->query('SELECT * FROM label_printers ORDER BY is_default DESC,status DESC,name')->fetchAll();foreach($rows as &$r){$r['dpi']=(int)$r['dpi'];$r['default_width_mm']=(float)$r['default_width_mm'];$r['default_height_mm']=(float)$r['default_height_mm'];$r['copies']=(int)$r['copies'];$r['is_default']=(bool)$r['is_default'];$r['settings']=rh24_json_decode((string)($r['settings_json']??''),[]);unset($r['settings_json'],$r['bridge_token']);}unset($r);return $rows;}
function rh24_label_templates(): array {$rows=rh24_db()->query("SELECT * FROM label_templates WHERE status<>'deleted' ORDER BY is_favorite DESC,is_system DESC,name")->fetchAll();foreach($rows as &$r){$r['width_mm']=(float)$r['width_mm'];$r['height_mm']=(float)$r['height_mm'];$r['is_system']=(bool)$r['is_system'];$r['is_favorite']=(bool)$r['is_favorite'];$r['layout']=rh24_json_decode((string)$r['layout_json'],[]);unset($r['layout_json']);}unset($r);return $rows;}
function rh24_label_jobs(int $limit=100): array {$limit=max(1,min(300,$limit));$rows=rh24_db()->query("SELECT j.*,t.name template_name,p.name printer_name,u.display_name created_by_name FROM label_jobs j LEFT JOIN label_templates t ON t.id=j.template_id LEFT JOIN label_printers p ON p.id=j.printer_id LEFT JOIN users u ON u.id=j.created_by ORDER BY j.created_at DESC LIMIT {$limit}")->fetchAll();foreach($rows as &$r){$r['label_count']=(int)$r['label_count'];$r['copy_count']=(int)$r['copy_count'];$r['payload']=rh24_json_decode((string)($r['payload_json']??''),[]);unset($r['payload_json']);$r['created_at']=rh24_iso($r['created_at']);$r['printed_at']=rh24_iso($r['printed_at']);}unset($r);return $rows;}
function rh24_label_job_detail(string $id): array {$q=rh24_db()->prepare('SELECT * FROM label_jobs WHERE id=?');$q->execute([$id]);$job=$q->fetch();if(!$job)throw new RuntimeException('Druckauftrag nicht gefunden.');$q=rh24_db()->prepare('SELECT * FROM label_job_items WHERE job_id=? ORDER BY line_no');$q->execute([$id]);$items=$q->fetchAll();foreach($items as &$i){$i['copies']=(int)$i['copies'];$i['data']=rh24_json_decode((string)$i['data_json'],[]);unset($i['data_json']);}unset($i);$job['payload']=rh24_json_decode((string)($job['payload_json']??''),[]);unset($job['payload_json']);$job['items']=$items;return $job;}
function rh24_label_next_job_no(): string {$db=rh24_db();$key='label_next_job_no';$n=(int)rh24_setting_get($key,'1');rh24_setting_set($key,(string)($n+1));return 'LBL-'.date('Ymd').'-'.str_pad((string)$n,5,'0',STR_PAD_LEFT);}
function rh24_label_data(): array {
    rh24_label_ensure_ready();
    // V105.4: Produktdaten vor der Übergabe an das Etikettenstudio härten.
    // Alte/teilweise Datensätze dürfen keine leeren Auswahlkarten mehr erzeugen.
    $catalog=[];$defaults=rh24_default_catalog();
    foreach(rh24_catalog() as $id=>$p){
        $fb=$defaults[(string)$id]??[];
        $name=trim((string)($p['name']??$fb['name']??''));
        $sku=trim((string)($p['sku']??$fb['sku']??''));
        $article=trim((string)($p['article_no']??$fb['article_no']??''));
        $barcode=trim((string)($p['barcode']??$fb['barcode']??''));
        $pid=trim((string)$id);
        if($name==='')$name=trim((string)($fb['name']??''));
        if($name==='')$name=$article!==''?'Artikel '.$article:($sku!==''?'Artikel '.$sku:($pid!==''?'Artikel '.$pid:''));
        if($pid===''&&$name===''&&$sku===''&&$article===''&&$barcode==='')continue;
        $catalog[]=[
          'id'=>$pid!==''?$pid:($sku!==''?$sku:($article!==''?$article:$barcode)),
          'name'=>$name!==''?$name:'Unbenannter Artikel',
          'sku'=>$sku,'article_no'=>$article,'barcode'=>$barcode,
          'category'=>(string)($p['category']??$fb['category']??''),
          'price'=>(float)($p['effective_price']??$p['base']??$fb['base']??0),
          'unit'=>(string)($p['unit']??$fb['unit']??''),
          'stock'=>(int)($p['stock']??$fb['stock']??0),
          'minimum'=>(int)($p['minimum']??$fb['minimum']??0),
          'image'=>(string)($p['image']??$fb['image']??'')
        ];
    }
    usort($catalog,static fn(array $a,array $b)=>strnatcasecmp(($a['category']??'').' '.($a['name']??''),($b['category']??'').' '.($b['name']??'')));
    $customers=[];try{$rows=rh24_db()->query("SELECT id,name,company,street,zip,city,country,email,phone FROM customers ORDER BY updated_at DESC LIMIT 1000")->fetchAll();foreach($rows as $c)$customers[]=['id'=>$c['id'],'name'=>$c['name'],'company'=>$c['company'],'street'=>$c['street'],'zip'=>$c['zip'],'city'=>$c['city'],'country'=>$c['country']?:'Deutschland','email'=>$c['email'],'phone'=>$c['phone']];}catch(Throwable){}
    $orders=[];try{$rows=rh24_db()->query("SELECT order_no,customer_json,carrier,tracking,status FROM orders ORDER BY created_at DESC LIMIT 250")->fetchAll();foreach($rows as $o)$orders[]=['order_no'=>$o['order_no'],'customer'=>rh24_json_decode((string)$o['customer_json'],[]),'carrier'=>$o['carrier'],'tracking'=>$o['tracking'],'status'=>$o['status']];}catch(Throwable){}
    return ['schema'=>rh24_label_schema_health(rh24_db()),'printers'=>rh24_label_printers(),'media'=>rh24_label_media(),'templates'=>rh24_label_templates(),'jobs'=>rh24_label_jobs(),'products'=>$catalog,'customers'=>$customers,'orders'=>$orders,'settings'=>['default_printer'=>(string)rh24_setting_get('label_default_printer',''),'default_template'=>(string)rh24_setting_get('label_default_template','LT-PROD'),'auto_price_decimals'=>(int)rh24_setting_get('label_price_decimals','2'),'company_name'=>(string)rh24_setting_get('invoice_company_name','Räucherhaken24')]];
}
